insert into public.events (title, description, category, start_date, end_date, hours_text, venue, address, city, lat, lng, price_text, is_free, url, image_url, image_credit, highlights, tags) values
  ('Fiestas de las Américas', 'Oklahoma City''s largest Latino festival. The Parade of the Americas kicks things off, followed by a full day of family-friendly music, food, and culture along Calle Dos Cinco in Historic Capitol Hill.', 'festival', '2026-10-03', '2026-10-03', 'Parade 11 a.m.–1 p.m. · Festival 10 a.m.–7 p.m.', 'Historic Capitol Hill (Calle Dos Cinco)', '2512 S Harvey Ave', 'Oklahoma City', 35.4388, -97.5188, 'Free', true, 'https://www.historiccapitolhill.com/fiestas-de-las-americas', null, null, array['Parade route: from Scissortail Park south on Robinson to Calle Dos Cinco', 'Arrive before 11 a.m. to get a good spot along the parade route', 'Questions: events@historiccapitolhill.com · 405-768-5465']::text[], array['hispanic-heritage', 'parade', 'music']::text[]),
  ('Dale Dale Dale: The Art of the Piñata', 'An exhibition that treats the piñata as sculpture and explores its history and storytelling. It features handcrafted work by Mexican artists Mayra Reza and Rafael Salinas (Piñatas Aylin), from traditional forms to custom tornadoes, axolotls, vaqueros, and tacos.', 'art', '2026-09-17', '2026-11-01', null, 'Norman Firehouse Art Center', '444 S Flood Ave', 'Norman', 35.2175, -97.4527, null, false, 'https://www.normanfirehouse.com/upcomingexhibitions', null, null, array['Pairs well with Sam Noble''s "Lives of the Dead" for a one-day Norman trip', 'Curated to spotlight underrepresented parts of Latino culture']::text[], array['hispanic-heritage', 'exhibition', 'new']::text[]),
  ('"Lives of the Dead": The Day of the Dead in Mexican and Latin American Art', 'More than 1,000 years of Mexican and Latin American art: ofrendas, sugar skulls, contemporary paintings, and antique prints.', 'art', '2026-09-05', '2027-01-03', 'Tue–Sat 10 a.m.–5 p.m. · Sun 1–5 p.m. · Closed Mon', 'Sam Noble Museum', '2401 Chautauqua Ave', 'Norman', 35.1946, -97.4481, 'Included with admission: $12 adults, $10 seniors, $7 ages 4–17', false, 'https://samnoblemuseum.ou.edu', null, null, array['Children 3 and under and OU students get in free', 'Museum phone: 405-325-7977']::text[], array['hispanic-heritage', 'dia-de-los-muertos', 'exhibition']::text[]),
  ('OKC Festival de Vida y Muerte', 'Scissortail Park''s Day of the Dead celebration, with traditional ofrendas (altars), live music, food, and artisan goods from more than 80 vendors.', 'festival', '2026-11-01', '2026-11-01', 'Catrina Parade 5 p.m. · Catrina Contest 7 p.m.', 'Scissortail Park', '300 SW 7th St', 'Oklahoma City', 35.461, -97.519, null, false, 'https://www.scissortailpark.org/events/okc-festival-de-vida-y-muerte-dia-de-muertos/', null, null, array['Catrina & alebrije (pet) parade: dress up the whole family', 'Free kids'' arts and crafts']::text[], array['hispanic-heritage', 'dia-de-los-muertos']::text[]),
  ('Hispanic Fiesta at Scissortail Park', 'A celebration of Hispanic cultures from many countries through music, dance, food, and a vendor showcase. The 2026 date hasn''t been confirmed yet.', 'festival', null, null, '2026 date not yet confirmed', 'Scissortail Park', '300 SW 7th St', 'Oklahoma City', 35.461, -97.519, null, false, 'https://www.scissortailpark.org/calendar/', null, null, array['Check the Scissortail Park calendar before planning around it']::text[], array['hispanic-heritage']::text[]),
  ('Oklahoma State Fair', 'Eleven days of rides, fair food, livestock, exhibits, and concerts at OKC Fair Park.', 'festival', '2026-09-17', '2026-09-27', 'Buildings: Sun–Thu 10 a.m.–9 p.m., Fri–Sat 10 a.m.–10 p.m. · Carnival opens 1 p.m. weekdays, 11 a.m. weekends', 'OKC Fair Park', '3001 General Pershing Blvd', 'Oklahoma City', 35.479, -97.569, 'Gate admission varies by day; kids 5 and under free', false, 'https://okstatefair.com/information/hours-admissions/', null, null, array['Buy tickets online, at the Fair Park box office, by phone (405-948-6800), or at metro OnCue stores', 'Final weekend: the fair ends Sunday, Sept. 27']::text[], array['fall', 'family']::text[]),
  ('Centennial Route 66 Balloon Festival', 'A five-day Route 66 centennial celebration with more than a dozen hot air balloons, tethered balloon rides, helicopter rides, kite shows, an art walk, live music, food trucks, and a vendor market.', 'festival', '2026-09-23', '2026-09-27', null, 'Parkhurst Ranch', '14816 E 2nd St', 'Arcadia', 35.6545, -97.3385, null, false, null, null, null, array['Officially recognized by the Oklahoma Route 66 Centennial Commission', 'Balloon flights depend on wind and weather, so check before you go']::text[], array['fall', 'family']::text[]),
  ('27th Annual Plaza District Festival', 'One of OKC''s biggest arts festivals, drawing 30,000+ people. Live music, 40+ local artist vendors, about 10 food trucks, and the 11th annual Plaza Walls Mural Expo along NW 16th Street.', 'festival', '2026-09-26', '2026-09-26', 'Noon–11 p.m. · Headliner Bella Burns at 10 p.m.', 'Plaza District', '1700 NW 16th St', 'Oklahoma City', 35.4866, -97.5452, 'Free', true, 'https://plazadistrict.org/plaza-fest', null, null, array['Family Zone: art activities, face painting, balloon animals, and street dance', '60+ local businesses take part']::text[], array['fall', 'music', 'art']::text[]),
  ('31st Annual Mesta Festa', 'A neighborhood festival in Perle Mesta Park with live music, a beverage garden, sand volleyball, kubb and bocce, food trucks, snow cones, local artists, and pop-up shops.', 'festival', '2026-09-27', '2026-09-27', 'Noon–6 p.m.', 'Perle Mesta Park', '1900 N Shartel Ave', 'Oklahoma City', 35.489, -97.5265, 'Free (beverage garden wristband $25)', true, 'https://mestapark.org/mesta-festa/', null, null, array['Kid-friendly, with a dedicated kids'' activity area and crafts']::text[], array['fall', 'family', 'music', 'new']::text[]),
  ('Pumpkinville: Road to Route 66', 'Thousands of pumpkins, seasonal displays, family activities, and giant pumpkin murals inspired by Route 66 landmarks.', 'family', '2026-10-01', '2026-10-25', 'Thu, Sun & Mon 10 a.m.–5 p.m. · Fri–Sat 10 a.m.–8 p.m. · Closed Tue–Wed', 'Myriad Botanical Gardens', '301 W Reno Ave', 'Oklahoma City', 35.4655, -97.5165, '$15 online / $16 at the gate (ages 3+)', false, 'https://myriadgardens.org/visit-us/seasonal/pumpkinville/', null, null, array['All-inclusive pass also covers the Crystal Bridge Conservatory and unlimited carousel rides', 'Free for ages 2 and under and for Myriad Gardens members']::text[], array['fall', 'family', 'pumpkins']::text[]),
  ('Asian Night Market Festival', 'One of Oklahoma''s largest cultural festivals, with more than 100 vendors and experiences filling Classen Boulevard in OKC''s Asian District.', 'festival', '2026-10-02', '2026-10-03', null, 'Military Park & Classen Blvd (NW 23rd–27th)', '2520 N Classen Blvd', 'Oklahoma City', 35.4968, -97.5305, 'Free', true, 'https://www.asiandistrictok.com/anmf', null, null, array[]::text[], array['fall', 'food']::text[]),
  ('40th Annual Greek Festival', 'Live music and dancing, Greek food and homemade pastries, a Greek market, and shopping boutiques.', 'festival', '2026-10-02', '2026-10-04', 'Fri–Sat 10 a.m.–10 p.m. · Sun 11 a.m.–4 p.m.', 'St. George Greek Orthodox Church', '2101 NW 145th St', 'Oklahoma City', 35.6215, -97.5445, null, false, 'https://www.greekfestokc.com/', null, null, array['Tickets and info: greekfestokc.com · 405-820-2942']::text[], array['fall', 'food']::text[]),
  ('Wings Fall Festival & Pumpkin Patch', 'Pumpkins, fall decor, hayrides, games, inflatables, and a petting zoo, supporting Wings, a special-needs community.', 'family', '2026-10-02', '2026-10-18', 'Weekends only · Fri–Sat 10 a.m.–6 p.m. · Sun 1–6 p.m.', 'Wings (new location)', '1349 E Wilshire Blvd', 'Oklahoma City', 35.5672, -97.4895, '$8 · family 4-pack $28 · ages 2 and under free', false, 'https://www.wingsok.org/festival', null, null, array['New location this year, so double-check the address before you drive', 'Info: 405-242-4646']::text[], array['fall', 'family', 'pumpkins']::text[]),
  ('Orr Family Farm Fall Festival', 'A pumpkin patch plus 25+ attractions: hayrides, Cannon Blasters, Trick ''Orr'' Treat, a lighted trail, and festival food.', 'family', '2026-09-19', '2026-11-14', 'Select dates · Early-October weekends: Fri–Sat 10 a.m.–10 p.m., Sun 10 a.m.–6 p.m.', 'Orr Family Farm', '14400 S Western Ave', 'Oklahoma City', 35.328, -97.5304, null, false, 'https://www.orrfamilyfarm.com/calendar', null, null, array['Admission is good for one entry on any date of the fall season', 'Add-ons include pony rides, gemstone mining, and paintball (see orrfamilyfarm.com/pricing)']::text[], array['fall', 'family', 'pumpkins']::text[]),
  ('Downtown Norman Fall Festival', 'Main Street turns into a Halloween block party with trick-or-treating, rides, inflatables, fire-engine lights, costume contests, and a live DJ.', 'block_party', '2026-10-23', '2026-10-23', '6–9 p.m.', 'Main Street, 100–300 blocks', 'E Main St', 'Norman', 35.2208, -97.4436, 'Free', true, 'https://www.visitnorman.com/events/annual-events/downtown-norman-fall-festival/', null, null, array['Main Street closes to cars during the event']::text[], array['fall', 'family', 'halloween']::text[]),
  ('Storybook Forest', 'A not-so-scary alternative to trick-or-treating. Kids walk a lit forest path collecting candy from storybook characters, then gather at the campfire for hot dogs, s''mores, hot chocolate, and read-alouds, plus a hayride and game area.', 'family', '2026-10-23', '2026-10-30', '5:30–8:30 p.m. nightly (come and go; arrive after 5:15)', 'Arcadia Lake – Spring Creek Park', '7200 E 15th St', 'Edmond', 35.638, -97.386, '$15 per child, $5 per adult', false, 'https://www.edmondok.gov/1599/Storybook-Forest', null, null, array['Buy tickets in advance: capped at 600 child tickets per night', 'Bring your printed or digital confirmation; tickets are good only for the night listed', 'Cash only on site; no pets or outside food', '2.5 miles east of I-35 on 15th Street']::text[], array['fall', 'family', 'halloween', 'new']::text[]),
  ('OKC Parks Halloween Harvest', 'Free come-and-go Halloween parties at OKC community centers with trick-or-treating, games, face painting, crafts, and food. Activities vary by location.', 'family', '2026-10-31', '2026-10-31', null, 'OKC community centers (several locations)', null, 'Oklahoma City', null, null, 'Free', true, 'https://www.okc.gov/departments/parks-recreation/halloween-happenings/-seldept-7', null, null, array['In past years it ran 5–8 p.m. at six community centers; check okc.gov for 2026 locations']::text[], array['fall', 'family', 'halloween']::text[]),
  ('Turkey Shoot Free Throw Contest', 'Shoot 10 free throws. The top shooter in each age division wins a Thanksgiving turkey.', 'family', '2026-11-13', '2026-11-13', '6–8 p.m.', 'The Station Recreation Center', '700 S Broadway Ave', 'Moore', 35.3288, -97.486, 'Free (registration required)', true, 'https://www.cityofmoore.com/upcoming-events/turkey-shoot-free-throw-contest', null, null, array['Online registration only; it opens Oct. 1', 'One turkey per family']::text[], array['family', 'sports', 'new']::text[]),
